<?php
declare(strict_types=1);defined('_JEXEC')or die;use Joomla\CMS\Language\Text;use Joomla\CMS\Router\Route;?>
<?php if($competitions===[]):?><div class="alert alert-info mb-0"><?php echo Text::_('MOD_JOOMLEAGUE_COMPETITIONS_EMPTY');?></div><?php else:?><div class="list-group"><?php foreach($competitions as$project):?><a class="list-group-item list-group-item-action" href="<?php echo Route::_('index.php?option=com_joomleague&view=project&project_id='.(int)$project->id);?>"><div class="d-flex justify-content-between align-items-start gap-3"><strong><?php echo htmlspecialchars((string)$project->name,ENT_QUOTES,'UTF-8');?></strong><?php if((bool)$params->get('show_sport',1)):?><span class="badge text-bg-secondary"><?php echo htmlspecialchars((string)$project->sport_type_name,ENT_QUOTES,'UTF-8');?></span><?php endif;?></div><small class="text-body-secondary"><?php echo htmlspecialchars((string)$project->competition_name,ENT_QUOTES,'UTF-8');?><?php if((bool)$params->get('show_season',1)):?> <span aria-hidden="true">·</span> <?php echo htmlspecialchars((string)$project->season_name,ENT_QUOTES,'UTF-8');?><?php endif;?><?php if((bool)$params->get('show_organisation',1)&&$project->organisation):?> <span aria-hidden="true">·</span> <?php echo htmlspecialchars((string)$project->organisation,ENT_QUOTES,'UTF-8');?><?php endif;?></small><?php if((bool)$params->get('show_counts',1)):?><div class="d-flex gap-3 mt-2 small"><span><?php echo Text::sprintf('COM_JOOMLEAGUE_PROJECTS_ENTRY_COUNT',(int)$project->entry_count);?></span><span><?php echo Text::sprintf('COM_JOOMLEAGUE_PROJECTS_PROGRAM_COUNT',(int)$project->match_count);?></span></div><?php endif;?></a><?php endforeach;?></div><?php endif;?>
